SELECT Name, Country, Age FROM singer ORDER BY Age DESC LIMIT 100;
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT singer.Name, singer.Release_year FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.Age = (SELECT MIN(Age) FROM singer)
SELECT DISTINCT singer.Name, concert.Year AS release_year FROM singer INNER JOIN concert ON singer.Singer_ID = concert.Singer_ID WHERE concert.Year = (SELECT MAX(Song_release_year) FROM concert)
SELECT DISTINCT Country FROM singer JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE Age > 20;
SELECT DISTINCT Country FROM singer WHERE Age > 20;
SELECT singer.Country, COUNT(singer.Singer_ID) AS total_singers_per_country FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT DISTINCT singer.Country, COUNT(*) AS total_singers_per_nation FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT singer.Name AS Song_Name, singer.Age AS Age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age > (SELECT AVG(singer.Age) FROM singer)
SELECT s.Name, c.Concert_Name FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID JOIN stadium s_stadium ON c.Stadium_ID = s_stadium.Stadium_ID WHERE s.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Location, stadium.Name, concert.Year FROM concert JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year BETWEEN 5000 AND 10000;
SELECT s.Name, c.Location, c.Stadium_ID FROM singer s JOIN singer_in_concert c ON s.Singer_ID = c.Singer_ID JOIN concert c ON c.concert_ID = c.concert_ID WHERE c.Highest >= 5000 AND c.Highest <= 10000;
