SELECT Name, Capacity FROM stadium JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID WHERE Year > 2013 GROUP BY Name, Capacity ORDER BY Capacity DESC LIMIT 1
