SELECT country.Name, country.CountryCode, country.Language, country.Continent, country.Region, country.SurfaceArea, country.IndepYear, country.Population, country.LifeExpectancy, country.GNP, country.GNPOld, country.LocalName, country.GovernmentForm, country.Capital, countryCode2 FROM country INNER JOIN city ON country.CountryCode = city.CountryCode WHERE country.Continent = 'Asia' AND country.Region = 'Africa' AND country.CountryCode != NULL;
SELECT c.Name, c.CountryCode FROM city c JOIN country ON c.CountryCode = country.Code WHERE c.CountryCode IN (SELECT CountryCode FROM country WHERE Continent = 'Asia')
SELECT country.Code FROM country WHERE country.CountryCode NOT IN (SELECT countrylanguage.CountryCode FROM countrylanguage WHERE countrylanguage.IsOfficial = 0)
SELECT country.Code, country.Name, country.Continent, country.Region, country.SurfaceArea, country.IndepYear, country.Population, country.LifeExpectancy, country.GNP, country.GNPOld, country.LocalName, country.GovernmentForm, country.Capital, countrylanguage.Language, countrylanguage.IsOfficial, countrylanguage.Percentage FROM country LEFT JOIN countrylanguage ON country.Code = countrylanguage.CountryCode WHERE countrylanguage.IsOfficial = FALSE;
SELECT country.Code, countrylanguage.Language, countrylanguage.IsOfficial, countrylanguage.Percentage FROM countrylanguage INNER JOIN country ON countrylanguage.CountryCode = country.Code WHERE country.Name != 'English'
SELECT country.Code FROM country WHERE country.CountryCode NOT IN (SELECT countrylanguage.CountryCode FROM countrylanguage WHERE countrylanguage.IsOfficial = 0)
SELECT c.CountryCode, c.Name, c.District, c.Population FROM city c JOIN countrylanguage cl ON c.CountryCode = cl.CountryCode WHERE cl.Language != 'English' AND cl.IsOfficial = 0 ORDER BY c.CountryCode;
SELECT country.Code FROM country WHERE CountryCode NOT IN (SELECT CountryCode FROM country WHERE Language = 'English') AND CountryCode NOT IN (SELECT CountryCode FROM country WHERE CountryCode = 'US')
SELECT c.Name, c.CountryCode FROM city c JOIN countrylanguage cl ON c.CountryCode = cl.CountryCode WHERE cl.IsOfficial = FALSE AND cl.Language = 'English'
SELECT DISTINCT city.Name, countrylanguage.Language AS Language FROM city JOIN countrylanguage ON city.CountryCode = countrylanguage.CountryCode WHERE countrylanguage.IsOfficial = TRUE AND countrylanguage.Language = 'Chinese'
SELECT DISTINCT Name FROM city INNER JOIN country ON city.CountryCode = country.Code WHERE country.Continent = 'Asia' AND country.Language.IsOfficial = '1'
SELECT Name, IndependenceYear, SurfaceArea, COUNT(*) AS NationalityCount FROM country UNION ALL SELECT Name, IndependenceYear, SurfaceArea FROM countrylanguage WHERE Language = 'English' GROUP BY Name, IndependenceYear, SurfaceArea ORDER BY COUNT(*) ASC;
SELECT CountryName, IndepYear, SurfaceArea FROM country WHERE Population < (SELECT MIN(Population) FROM city)
SELECT c.Name, c.Population, c.CountryCode AS country FROM city c JOIN country ON c.CountryCode = country.Code WHERE country.SurfaceArea > (SELECT MAX(Population) FROM city)
SELECT COUNT(DISTINCT District), COUNT(City) FROM city GROUP BY District HAVING AVG(Population) > District.Population;
SELECT c.District, COUNT(c.District) AS total_cities, AVG(c.Population) AS average_people FROM city c JOIN country ON c.CountryCode = country.Code GROUP BY c.District
SELECT Name, SurfaceArea FROM country ORDER BY SurfaceArea DESC LIMIT 5
SELECT CountryName, Population FROM country ORDER BY Population DESC LIMIT 3;
SELECT CountryName, Population FROM country ORDER BY Population DESC LIMIT 3;
SELECT CountryName FROM country WHERE Population ORDER BY Population LIMIT 3
SELECT CountryName, COUNT(*) AS NumberOfPeople FROM city JOIN country ON city.CountryCode = country.Code GROUP BY CountryName ORDER BY NumberOfPeople DESC LIMIT 3;
