SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals INNER JOIN Dogs ON Dogs.owner_id = Professionals.owner_id INNER JOIN Owners ON Owners.owner_id = Professionals.owner_id WHERE Owners.state = 'Indiana' OR Professionals.cell_number IS NOT NULL;
SELECT o.last_name, o.last_name, o.cell_number FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id WHERE o.state = 'Indiana' OR p.role_code = 'TREATMENT' AND p.date_of_treatment > '0000-00-00'
SELECT Dogs.name, Owners.first_name, Owners.last_name, Owners.street, Owners.city, Owners.state, Owners.zip_code, Owners.email_address, Owners.home_phone, Owners.cell_number FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.owner_id IS NOT NULL AND Dogs.treatment_type_code IS NOT NULL AND Dogs.charge_amount > 1000;
SELECT o.first_name, o.last_name, o.owner_id FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id ORDER BY d.dog_id DESC;
SELECT Dogs.id, Dogs.first_name, Dogs.last_name, Dogs.owner_id, Dogs.breed_code, Dogs.size_code, Dogs.name, Dogs.age, Dogs.date_of_birth, Dogs.gender, Dogs.weight, Dogs.date_arrived, Dogs.date_departed FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.weight DESC LIMIT 1;
