SELECT Dogs.id, Dogs.role, Dogs.first_name FROM Dogs JOIN Treatments ON Dogs.dog_id = Treatments.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Treatments.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'Two or more treatments')
SELECT treatment_type_description FROM Treatment_Types WHERE treatment_type_code IN (SELECT treatment_type_code FROM Charges WHERE charge_type = 'charge' AND cost_of_treatment = (SELECT MIN(cost_of_treatment) FROM Charges))
SELECT treatment_type_description FROM Treatment_Types ORDER BY cost_of_treatment ASC LIMIT 1;
SELECT o.owner_id, o.zip_code, d.dog_id, d.name, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_departed, t.treatment_type_description, t.cost_of_treatment FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code WHERE t.cost_of_treatment > (SELECT MAX(t.cost_of_treatment) FROM Treatments t) GROUP BY o.owner_id, o.zip_code, d.dog_id, d.name, d.date_of_birth, d.gender, d.weight, d.date_arrived, d.date_departed, t.treatment_type_description, t.cost_of_treatment;
SELECT Dogs.id, Dogs.zip_code FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Treatments.dog_id = Dogs.dog_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT Professionals.first_name, Professionals.last_name FROM Professionals JOIN Treatments ON Treatments.professional_id = Professionals.professional_id JOIN Dogs ON Dogs.dog_id = Treatments.dog_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatment_Types t ON d.size_code = t.size_code JOIN Sizes s ON d.size_code = s.size_code JOIN Professionals p ON d.professional_id = p.professional_id WHERE t.treatment_type_description = 'Less expansive' ORDER BY o.first_name, o.last_name;
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' GROUP BY Dogs.name, Owners.first_name
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' AND Owners.street IS NOT NULL;
SELECT Owners.last_name FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age DESC LIMIT 1;
SELECT Owners.email_address FROM Owners JOIN Professionals ON Professionals.owner_id = Owners.owner_id WHERE Owners.state = 'Hawaii' OR Owners.state = 'Wisconsin' AND Professionals.email_address IS NOT NULL;
SELECT email_address FROM Owners INNER JOIN Dogs ON Owners.owner_id = Dogs.owner_id INNER JOIN Professionals ON Dogs.dog_id = Professionals.professional_id WHERE state = 'Hawaii' OR state = 'Wisconsin' LIMIT 100;
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs;
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs;
SELECT MAX(cost_of_treatment) FROM Treatments;
SELECT MAX(cost_of_treatment) FROM Treatments;
SELECT Dogs.name, Dogs.age, Dogs.weight FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id;
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC;
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC;
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Citizenship != 'French' AND Name IS NOT NULL;
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949)
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949) WITHIN (DISTINCT)
SELECT Name FROM singer WHERE Net_Worth_Millions = (SELECT MAX(Net_Worth_Millions) FROM singer)
SELECT DISTINCT Citizenship, COUNT(*) AS Number_of_Singers_per_Citizenship FROM singer GROUP BY Citizenship;
SELECT singer.Citizenship, COUNT(singer.Singer_ID) AS count FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Citizenship
SELECT DISTINCT Citizenship FROM singer ORDER BY Citizenship ASC LIMIT 1
SELECT DISTINCT singer.Name, song.Sales, song.Highest_Position FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID;
SELECT DISTINCT Citizenship, MAX(Net_Worth_Millions) AS Max_Net_Worth FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID GROUP BY Citizenship;
SELECT MAX(Singer.Net_Worth_Millions) AS Max_Net_Worth FROM singer;
SELECT DISTINCT singer.Name FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Sales > 300000;
SELECT DISTINCT Name FROM singer WHERE Net_Worth_Millions > 300000;
